-- Patient Safety & Quality Improvement: Part 1 (Questions 1-50)
-- US MD / MBBS / USMLE Step 3
-- Target: Supabase (PostgreSQL)
-- Topic Slug: ethics-patient-safety

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'ethics-patient-safety' LIMIT 1;
    IF v_topic_id IS NULL THEN
        RAISE EXCEPTION 'Topic slug ethics-patient-safety not found.';
    END IF;

    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    -- SYSTEMS APPROACH & ERROR MODELS
    (v_topic_id, 'In the "Swiss Cheese Model" of system failure, what do the "holes" in the cheese represent?', '["Effective safety barriers", "Individual healthcare providers", "Latent conditions and active failures", "The patient''s comorbidities"]', 2, 'In James Reason''s Swiss Cheese Model, the holes represent weaknesses in the system''s layers of defense. When these holes (latent conditions and active failures) align, an error reaches the patient.'),
    (v_topic_id, 'Which of the following is considered a "latent error" in a hospital system?', '["A nurse administering the wrong dose of insulin", "A resident forgetting to order a STAT EKG", "Confusingly similar packaging for heparin and saline vials", "A surgeon making a wrong-site incision"]', 2, 'Latent errors are system-level flaws (the "accidents waiting to happen") such as poor equipment design, inadequate staffing, or look-alike/sound-alike drug packaging. The others are active failures.'),
    (v_topic_id, 'The "sharp end" of a medical error refers to:', '["The hospital board of directors", "The point of direct contact between a provider and a patient", "The manufacturing plant where equipment is designed", "The administrative policy-making committee"]', 1, 'The "sharp end" is the point where providers (nurses, physicians, etc.) interact directly with patients. Active failures occur at the sharp end, while latent errors occur at the "blunt end" (administration, design).'),
    (v_topic_id, 'A "Just Culture" in healthcare is best defined as one that:', '["Punishes every error to ensure accountability", "Ignores errors to maintain staff morale", "Distinguishes between human error and reckless behavior while encouraging reporting", "Blames the most senior physician for all team errors"]', 2, 'A Just Culture encourages reporting of errors and near misses by not punishing honest human errors, but still maintains accountability for reckless or intentional misconduct.'),
    (v_topic_id, 'What is the primary goal of the "Systems Approach" to patient safety?', '["To identify and fire the individual responsible for an error", "To redesign the environment to minimize the occurrence and impact of human error", "To increase the number of lawsuits against hospitals", "To eliminate the need for physician training"]', 1, 'The Systems Approach recognizes that humans are fallible and focuses on redesigning the system (barriers, forcing functions, etc.) to catch or mitigate errors before they cause harm.'),

    -- ERROR CLASSIFICATIONS
    (v_topic_id, 'An error that is caught before it reaches the patient is classified as a:', '["Sentinel event", "Near miss", "No-harm event", "Preventable adverse event"]', 1, 'A near miss (or "close call") is an error that had the potential to cause harm but was intercepted before it reached the patient.'),
    (v_topic_id, 'A patient receives the wrong medication due to a pharmacy error but suffers no clinical side effects. This is classified as a:', '["Near miss", "No-harm event", "Sentinel event", "Non-preventable adverse event"]', 1, 'A no-harm event is an error that REACHES the patient but results in no discernible harm.'),
    (v_topic_id, 'The Joint Commission (TJC) defines a "Sentinel Event" as an unexpected occurrence involving:', '["A minor medication error caught by a nurse", "A near miss in the operating room", "Death, permanent harm, or severe temporary harm", "A patient complaint about food quality"]', 2, 'Sentinel events are major safety incidents resulting in death, permanent harm, or severe temporary harm (e.g., wrong-site surgery, infant abduction, or suicide in a 24-hour facility).'),
    (v_topic_id, 'Which of the following is considered a "Never Event"?', '["A post-operative infection after a complex surgery", "Pressure ulcers acquired during a hospital stay", "Death from an untreatable malignancy", "A drug side effect listed in the package insert"]', 1, 'Never Events are particularly shocking medical errors (like stage 3/4 pressure ulcers, retained foreign bodies, or wrong-site surgery) that should never occur if standard safety protocols are followed.'),
    (v_topic_id, 'An adverse event that occurs despite following all current standards of care is known as:', '["A preventable error", "A non-preventable adverse event", "A sentinel event", "Malpractice"]', 1, 'Non-preventable adverse events (e.g., an allergic reaction in a patient with no known allergies) are complications that occur despite correct management.'),

    -- COGNITIVE BIASES IN MEDICINE
    (v_topic_id, 'A physician diagnoses a patient with "viral flu" because they have seen ten other cases of flu that morning, despite the patient having a stiff neck and photophobia. This is an example of:', '["Anchoring bias", "Availability heuristic", "Confirmation bias", "Blind spot bias"]', 1, 'The availability heuristic is the tendency to judge the probability of an event based on how easily recent or dramatic examples come to mind.'),
    (v_topic_id, 'A resident fixates on a diagnosis of "Pneumonia" based on an initial cough and fails to reconsider despite a negative chest X-ray and new-onset leg swelling. This is:', '["Framing effect", "Anchoring bias", "Hindsight bias", "Sunk cost fallacy"]', 1, 'Anchoring bias is the tendency to fixate on initial information and fail to adjust one''s thinking as new information becomes available.'),
    (v_topic_id, 'A surgeon reviews a complication after the fact and believes the outcome was "obvious" and could have been easily avoided, ignoring the uncertainty present at the time. This is:', '["Confirmation bias", "Hindsight bias", "Outcome bias", "Availability bias"]', 1, 'Hindsight bias (the "I-knew-it-all-along" effect) is the tendency to see past events as more predictable than they actually were.'),
    (v_topic_id, 'A physician only pays attention to lab results that support their suspected diagnosis of hyperthyroidism while ignoring a normal TSH. This is:', '["Availability heuristic", "Confirmation bias", "Representativeness heuristic", "Premature closure"]', 1, 'Confirmation bias is the tendency to search for, interpret, and favor information that confirms one''s pre-existing beliefs while ignoring contradictory evidence.'),
    (v_topic_id, '"Premature closure" in the diagnostic process is best described as:', '["Discharging a patient before they are stable", "The tendency to stop the diagnostic process once a potential diagnosis is found", "Ordering too many tests at once", "Asking for a second opinion too early"]', 1, 'Premature closure is stopping the search for a diagnosis once a "likely" one is identified, often leading to missed secondary or correct diagnoses.'),

    -- HUMAN FACTORS & ERGONOMICS
    (v_topic_id, 'The science of designing equipment and work environments to match human capabilities and limitations is called:', '["Biostatistics", "Human Factors Engineering (Ergonomics)", "Epidemiology", "Hospital Administration"]', 1, 'Human Factors Engineering focuses on making the system "error-resistant" by accounting for human psychology and physiology in design.'),
    (v_topic_id, 'Which of the following is the most effective "Human Factors" intervention to prevent medication errors?', '["A memo reminding staff to be more careful", "A mandatory lecture on medication safety", "Standardizing the concentrations of high-alert medications", "A monthly quiz for nurses"]', 2, 'Standardization is a strong human factors intervention because it reduces variation and cognitive load, unlike "reminders" which rely on human memory and vigilance.'),
    (v_topic_id, 'In human factors engineering, a "forcing function" is a design feature that:', '["Forces the user to work faster", "Makes it impossible to perform a task incorrectly", "Reminds the user of a potential error with a loud beep", "Automatically reports an error to the supervisor"]', 1, 'A forcing function (like a car that won''t start unless in Park) is a physical or hard-coded barrier that prevents an error from occurring.'),
    (v_topic_id, 'Using "Tall Man Lettering" (e.g., hydrOXYzine vs. hydrALAzine) is a strategy intended to reduce:', '["Wait times in the pharmacy", "Look-alike/sound-alike (LASA) medication errors", "The cost of generic drugs", "The need for barcode scanning"]', 1, 'Tall Man lettering uses uppercase letters to highlight the differences between drugs with similar names, reducing the risk of selection errors.'),
    (v_topic_id, 'Which of the following is an example of "Simplification" in a clinical process?', '["Adding a second approval step for all prescriptions", "Reducing the number of clicks required to order a common lab test", "Increasing the number of items on a checklist", "Requiring a verbal report for every patient"]', 1, 'Simplification reduces the number of steps or choices in a process, thereby reducing the opportunities for error.'),

    -- PATIENT SAFETY BASICS
    (v_topic_id, 'According to the "To Err is Human" report (1999), most medical errors are caused by:', '["Lazy or incompetent healthcare workers", "Greedy insurance companies", "Faulty systems, processes, and conditions", "The lack of medical technology"]', 2, 'The landmark IOM report concluded that errors are mostly systemic, resulting from flaws in how care is organized and delivered.'),
    (v_topic_id, 'Which of the following is the first priority after a major medical error occurs?', '["Reporting the incident to the hospital board", "Ensuring the patient is safe and receives any necessary stabilization", "Calling the hospital''s legal counsel", "Removing the evidence from the medical record"]', 1, 'The immediate priority is always the safety and clinical stabilization of the patient.'),
    (v_topic_id, 'A "Never Event" is typically defined as an error that is:', '["Expensive", "Uncommon", "Unambiguous and largely preventable", "Caused by a physician"]', 2, 'Never Events are unambiguous (clearly identifiable), serious, and usually preventable if safety protocols are followed.'),
    (v_topic_id, 'What is the "Blunt End" of a medical system?', '["The nurses and physicians providing direct care", "The layers of administration, policy, and management", "The patient and their family", "The medical equipment itself"]', 1, 'The blunt end represents the administrative and organizational layers that create the conditions (latent errors) under which the "sharp end" (front-line staff) works.'),
    (v_topic_id, 'The "Swiss Cheese" analogy was developed by which researcher?', '["Abraham Flexner", "James Reason", "Donald Berwick", "Lucian Leape"]', 1, 'James Reason is the psychologist who developed the Swiss Cheese Model of system failure.'),

    -- TYPES OF BIAS CONTINUED
    (v_topic_id, 'A clinician assumes a patient''s shortness of breath is due to their obesity and "laziness" without considering pulmonary embolism. This is an example of:', '["Framing bias", "Implicit bias (Stereotyping)", "Anchoring bias", "Representativeness heuristic"]', 1, 'Implicit bias involves unconscious associations or stereotypes that affect our understanding, actions, and decisions.'),
    (v_topic_id, 'When a clinician is influenced by the way a case is presented (e.g., "90% survival rate" vs. "10% mortality rate"), this is called:', '["Framing effect", "Sunk cost fallacy", "Base rate neglect", "Dunning-Kruger effect"]', 0, 'The framing effect occurs when the presentation of information influences decision-making.'),
    (v_topic_id, 'The tendency to believe that one''s own clinical judgment is superior to evidence-based guidelines is:', '["Overconfidence bias", "Confirmation bias", "Blind spot bias", "Optimism bias"]', 0, 'Overconfidence bias can lead clinicians to ignore objective data or guidelines in favor of their "intuition."'),
    (v_topic_id, 'A physician continues a failing treatment plan because they have already spent significant time and money on it. This is the:', '["Sunk cost fallacy", "Status quo bias", "Omission bias", "Commission bias"]', 0, 'The sunk cost fallacy is the tendency to continue an endeavor once an investment in money, effort, or time has been made, even if the current evidence suggests it should be abandoned.'),
    (v_topic_id, '"Base rate neglect" refers to:', '["Ignoring the commonality of a disease when interpreting a test result", "Forgetting to check the patient''s heart rate", "Overestimating the rarity of common conditions", "Ignoring a patient''s insurance status"]', 0, 'Base rate neglect is a cognitive error where the underlying prevalence of a condition is ignored when evaluating diagnostic information.'),

    -- MORE SYSTEMS APPROACH
    (v_topic_id, 'Which of the following is a "high-reliability organization" (HRO) principle?', '["Sensitivity to operations", "Preoccupation with failure", "Deference to expertise", "All of the above"]', 3, 'HROs (like aviation or nuclear power) share principles including preoccupation with failure, reluctance to simplify, sensitivity to operations, commitment to resilience, and deference to expertise (not rank).'),
    (v_topic_id, 'Standardization of care is primarily intended to reduce:', '["Clinician autonomy", "Unwarranted variation in practice", "Hospital profits", "The time spent with patients"]', 1, 'Standardization reduces variation that is not based on patient needs, ensuring consistent application of evidence-based practices.'),
    (v_topic_id, 'An EHR system that requires a "Hard Stop" reason before overriding an allergy alert is using:', '["A forcing function", "A process measure", "A latent error", "Redundancy"]', 0, 'A digital "hard stop" is a form of forcing function that prevents the user from proceeding until a specific safety action is taken.'),
    (v_topic_id, 'Which is the most effective intervention for reducing handoff errors?', '["A memo to residents", "Standardizing the handoff process (e.g., I-PASS)", "Increasing the number of shift changes", "Using only verbal reports"]', 1, 'Standardizing handoffs with tools like I-PASS has been proven to significantly reduce medical errors.'),
    (v_topic_id, 'The "Five Whys" technique is most commonly used during:', '["Medical school interviews", "Root Cause Analysis (RCA)", "Patient satisfaction surveys", "Billing audits"]', 1, 'The "Five Whys" is an iterative interrogative technique used to explore the cause-and-effect relationships underlying a particular problem.'),

    -- ERROR DEFINITIONS & EXAMPLES
    (v_topic_id, 'Which of the following describes a "Diagnostic Error"?', '["Giving the wrong dose of a correctly chosen medication", "Delaying a diagnosis when the symptoms were clear", "A patient developing a known side effect of a drug", "Failure to follow up on a critical lab result"]', 1, 'Diagnostic errors include delayed, missed, or incorrect diagnoses.'),
    (v_topic_id, 'A nurse notices a doctor is about to perform a procedure on the wrong leg and speaks up. This is a:', '["Sentinel event", "Near miss", "Adverse event", "No-harm event"]', 1, 'Because the error was caught before it reached the patient, it is a near miss.'),
    (v_topic_id, 'Which of the following is a "Treatment Error"?', '["Failure to provide a preventive treatment", "Inappropriate execution of a surgical procedure", "Failure of a piece of equipment", "All of the above"]', 3, 'Treatment errors encompass errors in procedures, drug administration, dosing, and equipment failure.'),
    (v_topic_id, 'A patient falls in the hospital because the call light was out of reach. This is an example of:', '["A latent system error (equipment placement)", "An active failure only", "A non-preventable complication", "Natural progression of aging"]', 0, 'The placement of equipment (latent error) created the conditions for the fall.'),
    (v_topic_id, 'The concept of "Resilience" in patient safety refers to:', '["The ability of a system to recover from an error", "The ability of a doctor to work 36 hours straight", "The patient''s ability to survive a complication", "Ignoring errors to keep moving forward"]', 0, 'Resilience is the capacity of a system to adapt and recover when things go wrong.'),

    -- COGNITIVE ERRORS CONTINUED
    (v_topic_id, 'When a clinician is influenced by the first piece of information offered (e.g., the triage note saying "Chest Pain"), they are at risk for:', '["Availability heuristic", "Anchoring bias", "Outcome bias", "Social loafing"]', 1, 'Anchoring is often driven by the first "data point" received.'),
    (v_topic_id, 'The "Representativeness Heuristic" leads clinicians to:', '["Judge a diagnosis based on how well the patient matches the \"classic\" textbook description", "Ignore common diseases", "Trust every lab result", "Assume every patient is typical"]', 0, 'This heuristic can lead to error if a patient has an atypical presentation of a common disease or a typical presentation of a rare disease.'),
    (v_topic_id, 'A physician blames a colleague for an error while attributing their own errors to "bad luck" or "a busy day." This is:', '["Fundamental attribution error", "Self-serving bias", "Both A and B", "Neither"]', 2, 'These are common psychological biases that hinder objective error analysis.'),
    (v_topic_id, 'Which bias involves judging a decision by its result rather than the quality of the decision at the time?', '["Outcome bias", "Hindsight bias", "Optimism bias", "Anchoring bias"]', 0, 'Outcome bias leads people to believe a bad decision was "good" if it happened to turn out okay, or vice versa.'),
    (v_topic_id, 'A "Heuristic" is best defined as:', '["A complex mathematical algorithm", "A mental shortcut or rule of thumb", "A standardized hospital policy", "A type of surgical tool"]', 1, 'Heuristics are mental shortcuts that allow for fast decision-making but can lead to systematic errors.'),

    -- SAFETY CULTURE
    (v_topic_id, 'What is the "Culture of Safety"?', '["A environment where everyone is afraid of being sued", "An organizational environment that prioritizes safety over all other goals", "A system where patients make all the decisions", "A hospital with the newest technology"]', 1, 'A safety culture involves a shared commitment to safety, open communication, and trust.'),
    (v_topic_id, 'In a "Just Culture," which behavior is most likely to result in disciplinary action?', '["Making a typo while tired", "Failing to follow a well-known safety protocol intentionally (Recklessness)", "Reporting a near miss", "Asking a question during a timeout"]', 1, 'Reckless behavior (conscious disregard for a substantial and unjustifiable risk) is the focus of discipline in a Just Culture.'),
    (v_topic_id, 'The "CUS" communication tool stands for:', '["Calm, Understand, Solve", "Concerned, Uncomfortable, Safety issue", "Check, Update, Sync", "Clear, Useful, Simple"]', 1, 'CUS is a graded assertiveness tool: "I am Concerned, I am Uncomfortable, this is a Safety issue."'),
    (v_topic_id, 'The "Two-Challenge Rule" encourages:', '["Doctors to challenge every nurse", "Staff to voice their concern at least twice if they feel a safety rule is being violated", "Patients to challenge their bills", "Administration to challenge all budget requests"]', 1, 'This rule empowers anyone on the team to "stop the line" if a concern is not addressed after two attempts.'),
    (v_topic_id, 'What is the primary purpose of a "Safety Huddle"?', '["To assign daily chores", "To share information about potential safety risks for the upcoming shift", "To perform a Root Cause Analysis", "To discuss hospital finances"]', 1, 'Safety huddles are brief, frequent meetings to increase "situational awareness" and identify risks.');
END $$;
